        width: min(960px, 100%);
        display: grid;
        gap: 18px;
        padding: 20px;
        border: 1px solid var(--border);
        border-radius: 28px;
        background: var(--surface);
        backdrop-filter: blur(16px);
        box-shadow: var(--shadow);
      }

      .image-frame {
        overflow: hidden;
        border-radius: 22px;
        background: #dbe7ff;
      }

      .image-frame img {
        display: block;
        width: 100%;
        height: min(60vh, 560px);
        object-fit: cover;
      }

      .preview-meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        flex-wrap: wrap;
      }

      .copy h1 {
        margin: 0 0 6px;
        font-size: clamp(1.4rem, 2.4vw, 2rem);
        line-height: 1.15;
      }

      .copy p {
        margin: 0;
        color: var(--muted);
      }

      .trigger,
      .secondary {
        appearance: none;
        border: 0;
        border-radius: 999px;
        font: inherit;
        font-weight: 600;
        padding: 0.9rem 1.2rem;
        cursor: pointer;
        transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
      }

      .trigger {
        background: var(--accent);
        color: #fff;
        box-shadow: 0 10px 24px rgba(225, 29, 72, 0.26);
      }

      .trigger:hover {
        background: var(--accent-hover);
        transform: translateY(-1px);
      }

      .secondary {
        background: #eef2ff;
        color: var(--text);
      }

      .secondary:hover {
        background: #e0e7ff;
      }

      .trigger:focus-visible,
      .secondary:focus-visible,
      dialog button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.35);
        outline-offset: 2px;
