        background: rgba(15, 23, 42, 0.58);
        backdrop-filter: blur(4px);
      }

      .dialog-panel {
        padding: 24px;
      }

      .dialog-title {
        margin: 0 0 10px;
        font-size: 1.25rem;
      }

      .dialog-copy {
        margin: 0;
        color: var(--muted);
        line-height: 1.55;
