          />
        </div>

        <div class="preview-meta">
          <div class="copy">
            <h1>Workspace shot</h1>
            <p>Preview the image and manage it from your library.</p>
          </div>

          <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
