          </button>
        </div>
      </section>
    </main>

    <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description">
      <div class="dialog-shell">
        <button class="close-icon" type="button" aria-label="Close dialog">×</button>
        <div class="dialog-panel">
          <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
          <p class="dialog-copy" id="delete-description">
            This will remove the image from your library. You can’t undo this action.
          </p>

          <div class="dialog-actions">
            <button class="secondary" type="button">Cancel</button>
            <button class="danger" type="button">Delete</button>
          </div>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = dialog.querySelector(".secondary");
      const closeButton = dialog.querySelector(".close-icon");
      const deleteButton = dialog.querySelector(".danger");

      const closeDialog = () => {
        dialog.close();
        trigger.focus();
      };

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", closeDialog);
      closeButton.addEventListener("click", closeDialog);

      deleteButton.addEventListener("click", () => {
        closeDialog();
      });
    </script>
  </body>
</html>
